      generic: "micafungin",
      aliases: ["Mycamine", "micafungine", "micafungin sodium", "echinocandin prophylaxis", "Candida cell wall inhibitor"],
      brandExamples: ["Mycamine"],
      class: "IV echinocandin antifungal; beta-(1,3)-D-glucan synthase inhibitor",
